:root {
  --bg-card: #fdf6e3;
  --bg-header: #2c3e2d;
  --bg-footer: #3a2e1e;
  --accent-gold: #c8972a;
  --accent-rust: #b5451b;
  --accent-teal: #2a7c6f;
  --text-dark: #1e1a12;
  --text-light: #fdf6e3;
  --text-muted: #7a6a4f;
  --dial-bg: #e8dfc8;
  --dial-ring: #8b7240;
  --needle-n: #b5451b;
  --needle-s: #2c3e2d;
  --chip-ok-bg: #d4edda;
  --chip-ok-text: #2a7c6f;
  --chip-warn-bg: #fff3cd;
  --chip-warn-text: #8a5c00;
  --bar-bg: #e0d8c8;
  --border-line: #c4a84f;
}

.calib-card {
  width: 480px;
  background: var(--bg-card);
  border: 2px solid var(--border-line);
  border-radius: 6px;
  overflow: hidden;
  font-size: 13px;
  color: var(--text-dark);
}

.calib-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
}

.calib-badge {
  font-size: 28px;
  color: var(--accent-gold);
  line-height: 1;
  flex-shrink: 0;
}

.calib-title-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.calib-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.calib-title {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-light);
  margin: 0;
  line-height: 1.1;
  letter-spacing: 0.02em;
}

.calib-serial {
  font-size: 10px;
  color: var(--text-muted);
  letter-spacing: 0.1em;
}

.calib-stamp {
  display: flex;
  flex-direction: column;
  align-items: center;
  border: 2px solid var(--accent-gold);
  border-radius: 4px;
  padding: 4px 8px;
  flex-shrink: 0;
}

.stamp-line {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--accent-gold);
}

.stamp-date {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-light);
  letter-spacing: 0.08em;
}

.calib-body {
  padding: 12px 14px;
}

.calib-grid {
  display: grid;
  grid-template-columns: 130px 1fr;
  gap: 14px;
  align-items: start;
}

.compass-dial {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  margin: 0;
}

.dial-ring {
  width: 110px;
  height: 110px;
  border-radius: 50%;
  border: 4px solid var(--dial-ring);
  background: var(--dial-bg);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dial-marks {
  position: absolute;
  inset: 0;
}

.mark {
  position: absolute;
  font-size: 11px;
  font-weight: 800;
  color: var(--text-dark);
  line-height: 1;
}

.mark.n { top: 5px; left: 50%; transform: translateX(-50%); }
.mark.e { right: 6px; top: 50%; transform: translateY(-50%); }
.mark.s { bottom: 5px; left: 50%; transform: translateX(-50%); }
.mark.w { left: 6px; top: 50%; transform: translateY(-50%); }

.needle-wrap {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transform: rotate(8deg);
}

.needle {
  width: 6px;
  height: 80px;
  border-radius: 3px 3px 0 0;
  background: linear-gradient(to bottom, var(--needle-n) 50%, var(--needle-s) 50%);
}

.dial-center {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent-gold);
  border: 2px solid var(--text-dark);
  position: absolute;
  z-index: 2;
}

.dial-caption {
  font-size: 10px;
  font-weight: 700;
  color: var(--accent-rust);
  letter-spacing: 0.05em;
  text-align: center;
}

.calib-readings {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.reading-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.reading-axis {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  width: 82px;
  flex-shrink: 0;
}

.reading-bar-wrap {
  flex: 1;
  height: 6px;
  background: var(--bar-bg);
  border-radius: 3px;
  overflow: hidden;
}

.reading-bar {
  display: block;
  height: 100%;
  border-radius: 3px;
}

.bar-full { width: 88%; background: var(--accent-rust); }
.bar-true { width: 100%; background: var(--accent-teal); }
.bar-dec  { width: 28%; background: var(--accent-gold); }
.bar-inc  { width: 72%; background: var(--bg-header); }

.reading-val {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-dark);
  width: 40px;
  text-align: right;
  flex-shrink: 0;
}

.calib-status-row {
  display: flex;
  gap: 6px;
  margin-top: 4px;
  flex-wrap: wrap;
}

.status-chip {
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 12px;
  letter-spacing: 0.04em;
}

.chip-ok {
  background: var(--chip-ok-bg);
  color: var(--chip-ok-text);
}

.chip-warn {
  background: var(--chip-warn-bg);
  color: var(--chip-warn-text);
}

.calib-footer {
  background: var(--bg-footer);
  display: flex;
  align-items: center;
  padding: 8px 14px;
  gap: 0;
}

.footer-field {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  padding: 0 10px;
}

.footer-field:first-child {
  padding-left: 0;
}

.field-key {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.field-val {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-light);
}

.footer-divider {
  width: 1px;
  height: 32px;
  background: var(--border-line);
  opacity: 0.4;
  flex-shrink: 0;
}
